const filterButtons=document.querySelectorAll(".filter-btn"),galleryItems=document.querySelectorAll(".gallery-item");filterButtons.forEach(e=>{e.addEventListener("click",()=>{const t=e.getAttribute("data-filter");filterButtons.forEach(e=>e.classList.remove("active")),e.classList.add("active"),galleryItems.forEach(e=>{const o=e.getAttribute("data-category");e.style.display="all"===t||o===t?"block":"none"})})});const lightbox=document.querySelector(".lightbox"),lightboxImg=document.querySelector(".lightbox-img"),lightboxTitle=document.querySelector(".lightbox-title"),lightboxCategory=document.querySelector(".lightbox-category"),lightboxClose=document.querySelector(".lightbox-close"),lightboxPrev=document.querySelector(".lightbox-prev"),lightboxNext=document.querySelector(".lightbox-next");let currentIndex=0,visibleItems=[];function updateVisibleItems(){visibleItems=Array.from(galleryItems).filter(e=>"none"!==window.getComputedStyle(e).display)}function openLightbox(e){const t=e.querySelector("img"),o=e.querySelector(".gallery-item-info h3").textContent,l=e.querySelector(".gallery-item-info p").textContent;lightboxImg.src=t.src,lightboxImg.alt=t.alt,lightboxTitle.textContent=o,lightboxCategory.textContent=l,lightbox.classList.add("active"),document.body.style.overflow="hidden"}function closeLightbox(){lightbox.classList.remove("active"),document.body.style.overflow=""}galleryItems.forEach((e,t)=>{e.addEventListener("click",()=>{updateVisibleItems(),currentIndex=visibleItems.indexOf(e),openLightbox(e)})}),lightboxClose.addEventListener("click",closeLightbox),lightbox.addEventListener("click",e=>{e.target===lightbox&&closeLightbox()}),lightboxPrev.addEventListener("click",e=>{e.stopPropagation(),currentIndex=(currentIndex-1+visibleItems.length)%visibleItems.length,openLightbox(visibleItems[currentIndex])}),lightboxNext.addEventListener("click",e=>{e.stopPropagation(),currentIndex=(currentIndex+1)%visibleItems.length,openLightbox(visibleItems[currentIndex])}),document.addEventListener("keydown",e=>{lightbox.classList.contains("active")&&("Escape"===e.key?closeLightbox():"ArrowLeft"===e.key?lightboxPrev.click():"ArrowRight"===e.key&&lightboxNext.click())}),console.log("Gallery loaded");